#include "owned-chain-erasures.h"

std::optional<charm::v1n7::linked_list::ChainEraseResult> charm::v1n7::linked_list::erase_owned_chain_positions(const std::vector<int>& values,const std::vector<std::size_t>& positions){struct Node{int value;std::unique_ptr<Node> next;explicit Node(int v):value(v){}};std::unique_ptr<Node> head;Node* tail=nullptr;for(int value:values){auto node=std::make_unique<Node>(value);Node* raw=node.get();if(tail)tail->next=std::move(node);else head=std::move(node);tail=raw;}ChainEraseResult result;std::size_t size=values.size();for(std::size_t position:positions){if(position>=size)return std::nullopt;std::unique_ptr<Node>* link=&head;for(std::size_t i=0;i<position;++i)link=&(*link)->next;result.removed.push_back((*link)->value);std::unique_ptr<Node> successor=std::move((*link)->next);*link=std::move(successor);--size;}for(Node* node=head.get();node;node=node->next.get())result.remaining.push_back(node->value);return result;}
